const float PI = 3.14159265358979323846264338327950288;

float casin(float x) {
	float negate = float(x < 0.0);
	x = abs(x);
	float ret = -0.0187293;
	ret *= x;
	ret += 0.0742610;
	ret *= x;
	ret -= 0.2121144;
	ret *= x;
	ret += 1.5707288;
	ret = PI*0.5 - sqrt(1.0 - x)*ret;
	return ret - 2.0 * negate * ret;
}

float atan2(float y, float x) {
 	float absx, absy, val;

     if (x == 0.0 && y == 0.0) {
 		return 0.0;
 	}
 	absy = y < 0.0 ? -y : y;
 	absx = x < 0.0 ? -x : x;
 	if (absy - absx == absy) {
 		return y < 0.0 ? -PI*2.0 : PI*2.0;
 	}

    if (absx - absy == absx) {
		val = 0.0;
    } else {
        val = casin((y/x)/sqrt(1.0+((y/x)*(y/x))));
    }
 	if (x > 0.0) {
 		return val;
 	}
 	if (y < 0.0) {
		return val - PI;
 	}
 	return val + PI;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Get a uv's corresponding to center of screen.
    vec2 center = vec2(0.5,0.5*iResolution.y/iResolution.x);
    vec2 uv = fragCoord/iResolution.x-center;
    // get polar uv's (these are static, can just be a texture.)
    vec2 puv = vec2(1.0-0.5*atan2(uv.y, uv.x)/PI, length(uv));
    // Output to screen
    float ang = iTime;
    float t = pow(1.0-abs(cos(puv.r*PI)*cos(ang)+sin(puv.r*PI)*sin(ang)),5.0);
    fragColor = vec4(0.0, t + 0.1*pow(abs(sin(puv.g*PI*20.0)),10.0),0.0,1.0);
}
